"""Which game probes still apply to code generated by the current editor:
base chain on a fresh regen of STCsrc, then each optional probe on its own copy."""
import os, shutil, subprocess, sys

Q = 'C:/tx/qp'
T = 'C:/tx/rigtest'
ED = 'F:/Projects/tyra-editor/build/tyrax-editor.exe'
LAPS = 'C:/Users/pawel/AppData/Local/Temp/claude/F--Projects-tyra-editor/c3b3c9b8-8cfd-4b28-888b-88bee4e424d0/scratchpad/patch_laps.py'
OPT = ['late', 'mute', 'batchlap', 'bakeev2', 'camskip', 'settlelap', 'gpuwait',
       'reblap', 'terrlap', 'chunklap', 'chunkid', 'emitlap', 'objlap', 'memmap',
       'bplap', 'awakevis', 'route', 'arm', 'warm', 'stampcen', 'site',
       'stamplap', 'cell']


def run(args):
    r = subprocess.run([sys.executable] + args, capture_output=True, text=True)
    out = (r.stdout + r.stderr).strip().splitlines()
    return r.returncode == 0, (out[-1] if out else '')[:100]


base = T + '/G0'
if os.path.exists(base):
    shutil.rmtree(base)
shutil.copytree(Q + '/STCsrc', base, ignore=shutil.ignore_patterns('bin'))
subprocess.run([ED, '--refresh-gen', base], capture_output=True)
for p in ['kf', 'kf2n', 'kf3']:
    print('%-10s' % p, *run([Q + '/patch_%s.py' % p, base]))
print('%-10s' % 'laps', *run([LAPS, base + '/src/gen/game_physics.gen.cpp']))
print('%-10s' % 'phys2', *run([Q + '/patch_phys2.py', base]))
for p in OPT:
    d = T + '/G_' + p
    if os.path.exists(d):
        shutil.rmtree(d)
    shutil.copytree(base, d, ignore=shutil.ignore_patterns('res', 'objects', 'preview*'))
    extra = ['x'] if p == 'flags' else []
    print('%-10s' % p, *run([Q + '/patch_%s.py' % p, d] + extra))
